"""CAS-persist generated reports; never blind rebase state."""
import subprocess
from common import ROOT
from git_state import RemoteState

if __name__=='__main__':
    paths=[str(p.relative_to(ROOT)) for p in (ROOT/'reports').glob('*') if p.is_file()]
    paths += [str(p.relative_to(ROOT)) for p in (ROOT/'data/qa').glob('*.json')]
    paths += ['data/state/checkpoint.json']
    # Reports are derived and regenerated by every run: a report another commit already moved past is left as it
    # is (never overwritten, never a failed job); the next run refreshes it.
    state=RemoteState();state.remember(paths);state.persist(paths,skip_conflicts=True)
    if state.skipped:print('REPORTS_SKIPPED_NEWER_ON_MAIN: '+', '.join(state.skipped))
